#!/usr/bin/env bash
# Start PortAgent from the bundle (Linux/macOS).
#
#   ./START.sh              -> interactive console menu
#   ./START.sh --gui        -> desktop GUI window (Tkinter)
#
# It sources env.sh (generated by install.sh) so the bundled tools are found.
set -u

BUNDLE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

if [ ! -f "$BUNDLE_DIR/env.sh" ]; then
    echo "env.sh missing -- running install.sh first ..."
    bash "$BUNDLE_DIR/install.sh" || exit 1
fi

# shellcheck disable=SC1091
. "$BUNDLE_DIR/env.sh"

PY=""
for c in python3 python; do
    if command -v "$c" >/dev/null 2>&1; then PY="$c"; break; fi
done
if [ -z "$PY" ]; then
    echo "python3 not found. Install Python 3.10+ and re-run." >&2
    exit 1
fi

cd "$BUNDLE_DIR"
exec "$PY" "$BUNDLE_DIR/run.py" "$@"
